// Assemble the Ironbound Strength Co. theme (6 Divi 5 pages for a strength and conditioning gym) into one pack. Unlike create-real-estate-pack.ts the pages are NOT
// generated by the pipeline's Claude workers: they are composed by the AI Editor for
// Divi 5 plugin from its section recipes (design language organic-warm + a style kit,
// validated by the real LayoutGate) in the validator repo:
//   php scripts/theme-packs/build.php ironbound     -> dist/theme-packs/ironbound/<role>.json
// and then run through every downstream gate here (validate, stock photos, design lint,
// mobile stacking, dedupe, SEO, real Divi render, critics, ingest).
//
//   npm run dev            # in another shell (ingest target)
//   set -a && . ./.env.local && set +a && IRON_DIR=<dir with the six json files> npx tsx scripts/create-ironbound-pack.ts
// Smoke test: THEME_ONLY_ROLES=home.
import { randomUUID } from 'node:crypto';
import { readFileSync } from 'node:fs';
import { eq, inArray } from 'drizzle-orm';
import { db } from '@/db/client';
import { packs, packLayouts, layouts } from '@/db/schema';
import { buildThemeDeps } from '@/pipeline/deps';
import { runThemePack, themePageSlug, type ThemeSpec, type ThemePage } from '@/pipeline/theme';
import type { Brief } from '@/pipeline/compose';

const DIR = process.env.IRON_DIR ?? '../Divi 5 Deterministic Validator/dist/theme-packs/ironbound';

const BRIEF: Brief = {
  businessType: 'service/agency',
  businessName: 'Ironbound Strength Co.',
  tagline: 'Get strong. Stay strong.',
  audience: 'adults of every level who want coached strength training in small groups, from first-time lifters to returning athletes',
  conversionGoal: 'start a free first week',
  primaryCta: 'Start your free week',
  accentColorHex: '#2438FF',
  voice: 'direct, confident and plain-spoken. Short sentences, specific details, no hype and no fitness clichés.',
  palette: { primary: '#2438ff', secondary: '#3d3d52', tint: '#ffd60a', dark: '#0c0c14', heading: '#0c0c14', body: '#3d3d52' },
  designNotes: 'Bold-vibrant design language: saturated yellow and cobalt blocks, black text, very heavy Unbounded headlines, Work Sans body, hard edges and heavy outlines.',
};

const BRAND_FACTS =
  'Ironbound Strength Co., 1180 Larimer Street, Denver, CO 80204. Phone (303) 555-0194. hello@ironbound.fit. ' +
  'Sample copy: names, prices and reviews are examples to replace.';

const ROLES: { role: string; roleLabel: string }[] = [
  { role: 'home', roleLabel: 'Home' },
  { role: 'programs', roleLabel: 'Programs' },
  { role: 'membership', roleLabel: 'Membership' },
  { role: 'coaches', roleLabel: 'Coaches' },
  { role: 'gym', roleLabel: 'The Gym' },
  { role: 'contact', roleLabel: 'Contact' },
];

const PAGES: ThemePage[] = ROLES.map((r) => ({
  ...r,
  flow: [],
  precomposed: readFileSync(`${DIR}/${r.role}.json`, 'utf8'),
}));

const SPEC: ThemeSpec = { niche: 'fitness', style: 'bold', color: 'yellow', brief: BRIEF, brandFacts: BRAND_FACTS, pages: PAGES };

const PACK_SLUG = 'ironbound-strength-gym-theme';
const PACK_TITLE = 'Ironbound: Strength & Conditioning Gym Theme (6 Pages)';
const PRICE_CENTS = 1200;
const DESCRIPTION =
  'A complete six-page Divi 5 website for a strength gym, CrossFit-style box or personal training studio, ready to make ' +
  'your own. Home, Programs, Membership, Coaches, The Gym and Contact share one loud, confident identity: saturated yellow ' +
  'and cobalt blocks, black type, very heavy headlines and hard edges. Every section is built from proven, validated ' +
  'recipes and a single design language and style kit, so buttons, accordions, forms and type match on every page, on ' +
  'desktop, tablet and phone. A programs grid, class guides, three-tier membership pricing with a comparison table, a ' +
  'coaches page with a founder note, a gym gallery, FAQs and a contact form with the gym details are all in place. ' +
  'Names, prices, hours and reviews are sample copy: swap in your own and publish. No lorem ipsum, no broken layouts. ' +
  'One simple commercial license, unlimited client sites.';
const PACK_SEO = {
  metaTitle: 'Ironbound: Strength Gym Theme for Divi 5 (6 Pages) | Divi5Lab',
  metaDescription:
    'A complete six-page Divi 5 website theme for a strength and conditioning gym: Home, Programs, Membership, Coaches, ' +
    'The Gym and Contact. One bold brand, real copy, pricing and booking sections.',
  keywords: [
    'divi 5 gym theme', 'fitness studio website template', 'crossfit gym divi template', 'personal trainer divi 5 theme',
    'strength training website template', 'divi 5 multi-page theme',
  ],
};

async function upsertPack(slugs: string[]): Promise<void> {
  const rows = await db
    .select({ id: layouts.id, slug: layouts.slug, previews: layouts.previewImageKeys })
    .from(layouts).where(inArray(layouts.slug, slugs));
  const bySlug = new Map(rows.map((r) => [r.slug, r]));
  const found = slugs.filter((s) => bySlug.has(s));
  if (found.length === 0) { console.error('no Ironbound pages found in DB — did ingest run?'); process.exitCode = 1; return; }
  if (found.length < slugs.length) console.warn(`only ${found.length}/${slugs.length} pages present; linking what exists`);

  const cover = bySlug.get(slugs[0])?.previews?.[0] ?? bySlug.get(found[0])!.previews?.[0] ?? null;
  const existing = (await db.select().from(packs).where(eq(packs.slug, PACK_SLUG)).limit(1))[0];
  const common = {
    title: PACK_TITLE, description: DESCRIPTION, kind: 'paid' as const,
    priceCents: PRICE_CENTS, stripePriceId: null, coverImageKey: cover, seo: PACK_SEO, status: 'published' as const,
  };
  let packId: string;
  if (existing) {
    packId = existing.id;
    await db.update(packs).set(common).where(eq(packs.id, packId));
  } else {
    packId = randomUUID();
    await db.insert(packs).values({ id: packId, slug: PACK_SLUG, ...common });
  }

  await db.delete(packLayouts).where(eq(packLayouts.packId, packId));
  await db.insert(packLayouts).values(found.map((s, i) => ({ packId, layoutId: bySlug.get(s)!.id, position: i })));

  console.log(`\nPack ready: /packs/${PACK_SLUG}  (paid, ${found.length} pages, cover=${cover ? 'set' : 'none'})`);
}

async function main() {
  const { deps, close } = await buildThemeDeps({ businessName: BRIEF.businessName, logPrefix: '[theme]', defaultMaxBudgetUsd: 1 });

  // Optional smoke-test knob: THEME_ONLY_ROLES=home,listings limits which pages generate.
  const onlyRoles = (process.env.THEME_ONLY_ROLES ?? '').split(',').map((s) => s.trim()).filter(Boolean);
  const spec: ThemeSpec = onlyRoles.length ? { ...SPEC, pages: SPEC.pages.filter((p) => onlyRoles.includes(p.role)) } : SPEC;

  console.log(`[theme] generating ${spec.pages.length} ${spec.niche} pages for "${BRIEF.businessName}"…`);
  const result = await runThemePack(spec, deps);
  await close();
  console.log('[theme] summary:', { generated: result.generated, ingested: result.ingested, dropped: result.dropped, deduped: result.deduped });

  if (onlyRoles.length) { console.log('[theme] partial run (THEME_ONLY_ROLES set) — skipping pack assembly'); return; }
  const expectedSlugs = SPEC.pages.map((p) => themePageSlug(BRIEF, SPEC, p));
  await upsertPack(expectedSlugs);
}

main().then(() => process.exit(0)).catch((e) => { console.error(e); process.exit(1); });
